'use client';
import {useState,useEffect,useRef,createContext,useContext,ReactNode} from 'react';
import Link from 'next/link';
import RichEditor from './RichEditor';
import HubIcon from './HubIcon';
import {State,Person,Appointment,Quote,Task,Template,seed,uid,day,nice,money,metrics,stages,treatments,nextSlot,personalise} from './data';
import {slotsFor,monthDays,shiftMonth,addDays} from '../../lib/consultation';
type Modal={type:string;person?:string;id?:string};
type Ctx={s:State;change:(fn:(s:State)=>void)=>void;open:(m:Modal)=>void;notify:(t:string)=>void;profile:(id:string)=>void};
const Context=createContext<Ctx>(null!);const useHub=()=>useContext(Context);
const nav=[['overview','Overview','◫'],['pipeline','Leads & Pipeline','▥'],['clients','Clients','♙'],['appointments','Appointments','▦'],['inbox','Inbox','✉'],['tasks','Tasks & Reminders','✓'],['email-templates','Templates','▤'],['automations','Automations','⌁'],['photos','Photo Library','▧'],['reports','Reports','↗'],['settings','Settings','⚙']];
export function Avatar({p}:{p?:Person}){return <span className="hub-avatar" style={{background:p?['#e9e1d7','#dde8e1','#e4e5ef','#f3e0d6'][p.name.length%4]:'#e9e1d7'}}>{p?.name.split(' ').map(v=>v[0]).join('')||'J'}</span>}
function Badge({children}:{children:ReactNode}){return <span className={'hub-badge '+(['Completed','Accepted','Won','Active'].includes(String(children))?'green':['Sent','Quote Sent','Follow-up due','High'].includes(String(children))?'orange':'')}>{children}</span>}
function Button({children,onClick,primary=false}:{children:ReactNode;onClick:()=>void;primary?:boolean}){return <button type="button" className={'hub-btn '+(primary?'primary':'')} onClick={onClick}>{children}</button>}
function Card({title,children,link}:{title:string;children:ReactNode;link?:string}){return <section className="hub-card"><div className="hub-card-head"><h2>{title}</h2>{link&&<Link href={'/portal/'+link+'/'}>View all ↗</Link>}</div>{children}</section>}
function record(s:State,person:string,text:string){s.activity.unshift({id:uid(),person,text,date:new Date().toISOString()})}
function send(s:State,person:string,text:string){s.messages.push({id:uid(),person,text,date:new Date().toISOString(),out:true,read:true});s.archived=s.archived.filter(x=>x!==person);record(s,person,'Simulated email: '+text.split('\n')[0])}
export default function Portal({section}:{section:string}){
 const [s,setS]=useState<State|null>(null),[modal,setModal]=useState<Modal|null>(null),[toast,setToast]=useState(''),[search,setSearch]=useState(''),[menu,setMenu]=useState(false),[quick,setQuick]=useState(false),[bell,setBell]=useState(false);const timer=useRef<ReturnType<typeof setTimeout>|null>(null);
 useEffect(()=>{try{const saved=JSON.parse(localStorage.getItem('hairlusion-clienthub-v1')||'null');setS(saved?.version===1&&Array.isArray(saved.people)&&Array.isArray(saved.workflows)?saved:seed())}catch{setS(seed())}},[]);
 useEffect(()=>{if(!s)return;try{localStorage.setItem('hairlusion-clienthub-v1',JSON.stringify(s))}catch{setToast('Browser storage is unavailable. Changes will last for this visit only.')}},[s]);
 useEffect(()=>()=>{if(timer.current)clearTimeout(timer.current)},[]);
 const notify=(t:string)=>{setToast(t);if(timer.current)clearTimeout(timer.current);timer.current=setTimeout(()=>setToast(''),4500)};
 const change=(fn:(s:State)=>void)=>setS(previous=>{if(!previous)return previous;const copy=structuredClone(previous);fn(copy);return copy});
 const profile=(id:string)=>{setSearch('');setBell(false);setModal({type:'profile',person:id})};
 if(!s)return <div className="hub-loading"><span>H</span><h1>Hairlusion ClientHub</h1><p>Preparing your workspace…</p></div>;
 const title=nav.find(x=>x[0]===section)?.[1]||'Overview',m=metrics(s);const results=search.trim()?s.people.filter(p=>(p.name+' '+p.treatment).toLowerCase().includes(search.toLowerCase())):[];
 return <Context.Provider value={{s,change,open:setModal,notify,profile}}><div className="hub">{menu&&<button className="hub-menu-shade" aria-label="Close navigation" onClick={()=>setMenu(false)}/>}<aside className={'hub-sidebar '+(menu?'open':'')}><Link className="hub-brand" href="/portal/">HAIRLUSION<span>ClientHub <b>WORKSPACE</b></span></Link><span className="hub-nav-label">YOUR BUSINESS</span><nav>{nav.map(([key,label,icon])=><Link key={key} href={key==='overview'?'/portal/':'/portal/'+key+'/'} aria-current={key===section?'page':undefined} onClick={()=>setMenu(false)}><i><HubIcon name={key}/></i>{label}{key==='inbox'&&<em>{s.messages.filter(x=>!x.read).length}</em>}</Link>)}</nav><div className="hub-sidebar-bottom"><span className="hub-live">● All changes saved on this device</span><div className="hub-joe"><Avatar/><div><strong>Joe · Hairlusion</strong><small>Administrator</small></div><Link href="/portal/settings/" aria-label="Settings">⚙</Link></div><Link href="/">↗ View public website</Link></div></aside><div className="hub-workspace"><header className="hub-header"><button className="hub-mobile-menu" onClick={()=>setMenu(!menu)} aria-label="Toggle navigation">☰</button><span className="hub-breadcrumb">Workspace <b>/</b> {title}</span><div className="hub-search"><span>⌕</span><input aria-label="Search clients, leads, appointments and quotations" placeholder="Search your workspace…" value={search} onChange={e=>setSearch(e.target.value)}/>{search&&<div className="hub-dropdown search-results"><button onClick={()=>setSearch('')}>Close search ×</button>{results.map(p=><button key={p.id} onClick={()=>profile(p.id)}><Avatar p={p}/><span>{p.name}<small>{p.kind} · {p.treatment}</small></span></button>)}{s.appointments.filter(a=>(a.type+' '+a.date+' '+s.people.find(p=>p.id===a.person)?.name).toLowerCase().includes(search.toLowerCase())).slice(0,5).map(a=><button key={a.id} onClick={()=>{setSearch('');setModal({type:'appointment',id:a.id,person:a.person})}}>▦ {a.type} · {nice(a.date)}</button>)}{s.quotes.filter(q=>(q.id+' '+q.status+' '+s.people.find(p=>p.id===q.person)?.name).toLowerCase().includes(search.toLowerCase())).slice(0,5).map(q=><button key={q.id} onClick={()=>{setSearch('');setModal({type:'quote',id:q.id,person:q.person})}}>▤ {q.id} · {money(q.amount)}</button>)}{!results.length&&<small>Search by name, treatment, appointment date or quote status.</small>}</div>}</div><div className="hub-header-action"><button className="hub-icon-button" aria-label="Notifications" onClick={()=>{setBell(!bell);setQuick(false)}}><HubIcon name="bell"/><b>{s.settings.notifications?m.tasks:0}</b></button>{bell&&<div className="hub-dropdown"><strong>{s.settings.notifications?'Reminders requiring attention':'Notifications paused in Settings'}</strong>{s.tasks.filter(t=>s.settings.notifications&&!t.done&&t.date<=day()).map(t=><button key={t.id} onClick={()=>profile(t.person)}>{t.title}<small>{nice(t.date)}</small></button>)}{m.tasks===0&&<p>You’re all caught up.</p>}</div>}</div><div className="hub-header-action"><Button primary onClick={()=>{setQuick(!quick);setBell(false)}}>＋ Quick add</Button>{quick&&<div className="hub-dropdown">{['lead','client','appointment','task','quote'].map(type=><button key={type} onClick={()=>{setQuick(false);setModal({type})}}>New {type==='quote'?'quotation':type}</button>)}</div>}</div><Avatar/></header><main className="hub-main"><div className="hub-page-heading"><div><p>HAIRLUSION CLIENTHUB</p><h1>{section==='overview'?'A little clarity. A better day.':title}</h1><span>{section==='overview'?"Good morning, Joe. Here’s what’s happening in your business.":({pipeline:'Every enquiry, thoughtfully guided to the next step.',clients:'The people behind your work. Every detail in one place.',appointments:'Make time for the conversations that matter.',inbox:'Personal conversations, all together.',tasks:'Small actions. Meaningful progress.','email-templates':'Your voice, ready when you need it.',automations:'Considered follow-ups, without the extra admin.',photos:'A visual record of every client journey.',reports:'See the bigger picture of your business.',settings:'A workspace that works for you.'} as Record<string,string>)[section]}</span></div><div className="hub-heading-actions">{section==='overview'?<span className="hub-date">◷ {nice(day())}</span>:['clients','pipeline','appointments','tasks'].includes(section)?<Button primary onClick={()=>setModal({type:({clients:'client',pipeline:'lead',appointments:'appointment',tasks:'task'} as Record<string,string>)[section]})}>＋ {({clients:'New client',pipeline:'Add lead',appointments:'New appointment',tasks:'New task'} as Record<string,string>)[section]}</Button>:null}</div></div>{section==='overview'?<Overview/>:section==='clients'?<Clients/>:section==='pipeline'?<Pipeline/>:section==='appointments'?<Calendar/>:section==='inbox'?<Inbox/>:section==='tasks'?<Tasks/>:section==='email-templates'?<Templates/>:section==='automations'?<Automations/>:section==='photos'?<Photos/>:section==='reports'?<Reports/>:<Settings/>}<footer className="hub-footer">Hairlusion ClientHub <span>Considered care. Connected business.</span></footer></main></div>{toast&&<div role="status" className="hub-toast">✓ {toast}</div>}{modal&&<ModalView modal={modal} close={()=>setModal(null)}/>}</div></Context.Provider>
}
function Kpis(){const {s}=useHub(),m=metrics(s);return <div className="hub-kpis">{[['Total clients',m.clients,'clients'],['Active leads',m.leads,'pipeline'],['Upcoming consultations',m.consultations,'appointments'],['Outstanding quotations',m.quotes,'pipeline'],['Follow-ups due',m.tasks,'tasks'],['Estimated pipeline',money(m.pipeline),'pipeline'],['Total revenue',money(m.revenue),'reports'],['Client conversion',m.conversion+'%','reports']].map(([label,value,path])=><Link className="hub-kpi" href={'/portal/'+path+'/'} key={label}><span>{label} <i>↗</i></span><strong>{value}</strong><small>{label==='Client conversion'?'Clients + won leads / all contacts':'From your current records'}</small></Link>)}</div>}
function PersonLine({id,sub}:{id:string;sub?:string}){const {s,profile}=useHub(),p=s.people.find(p=>p.id===id);return <button className="hub-person" onClick={()=>profile(id)}><Avatar p={p}/><span><strong>{p?.name||'Customer'}</strong><small>{sub||p?.treatment}</small></span></button>}
function Overview(){const {s,profile,open}=useHub();const upcoming=s.appointments.filter(a=>a.status==='Scheduled'&&a.date>=day()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).slice(0,5);return <><Kpis/><div className="hub-briefing"><div className="hub-briefing-icon">✧</div><div><strong>Joe’s daily briefing</strong><p>{s.appointments.filter(a=>a.date===day()&&a.status==='Scheduled').length} appointments today · {s.people.filter(p=>p.created===day()).length} new enquiries · {s.tasks.filter(t=>!t.done&&t.date<=day()).length} follow-ups need your attention.</p></div><Link href="/portal/tasks/">Plan my day →</Link></div><div className="hub-grid two-wide"><Card title="Revenue performance" link="reports"><RevenueChart/><p className="hub-chart-note">Recorded sample payments · GBP</p></Card><Card title="Your pipeline" link="pipeline"><PipelineSummary/></Card></div><div className="hub-grid two"><Card title="Coming up next" link="appointments">{upcoming.map(a=><div className="hub-list-row" key={a.id}><span className="hub-date-tile">{new Date(a.date+'T12:00:00Z').getUTCDate()}<small>{new Date(a.date+'T12:00:00Z').toLocaleString('en-GB',{month:'short'})}</small></span><PersonLine id={a.person} sub={a.type+' · '+a.format}/><button className="hub-time" onClick={()=>open({type:'appointment',id:a.id,person:a.person})}>{a.time} ↗</button></div>)}</Card><Card title="A few thoughtful next steps" link="tasks">{s.tasks.filter(t=>!t.done).slice(0,5).map(t=><TaskRow key={t.id} task={t}/>)}{s.tasks.every(t=>t.done)&&<p className="hub-empty">All tasks completed. A clear day ahead.</p>}</Card></div><div className="hub-grid two"><Card title="Recent activity">{[...s.activity].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6).map(a=><div className="hub-activity" key={a.id}><i/><div><button onClick={()=>profile(a.person)}>{s.people.find(p=>p.id===a.person)?.name}</button><p>{a.text}</p><small>{nice(a.date)}</small></div></div>)}</Card><Card title="Enquiry conversion" link="reports"><Conversion/><div className="hub-soft"><strong>Keep the conversation moving.</strong><p>Open a client record to review the next action, prepare a quotation or arrange a follow-up.</p><Link href="/portal/pipeline/">Explore your leads →</Link></div></Card></div></>}
function PipelineSummary(){const {s}=useHub();return <div className="hub-pipeline-summary">{stages.map((stage,i)=>{const n=s.people.filter(p=>p.kind==='lead'&&p.status===stage).length;return <div key={stage}><span><i style={{background:['#d9a978','#8fa6bc','#b4a6cb','#e7a36f','#8aa899','#b8b8b8'][i]}}/>{stage}<b>{n}</b></span><div><i style={{width:Math.max(2,n/Math.max(1,s.people.filter(p=>p.kind==='lead').length)*100)+'%'}}/></div></div>})}</div>}
function RevenueChart({from='',to='9999'}:{from?:string;to?:string}){const {s}=useHub();const months=Array.from({length:6},(_,i)=>shiftMonth(day().slice(0,7),i-5));const values=months.map(m=>s.payments.filter(p=>p.date.startsWith(m)&&p.date>=from&&p.date<=to).reduce((n,p)=>n+p.amount,0)),max=Math.max(...values,1);return <div className="hub-chart" role="img" aria-label="Monthly recorded revenue">{months.map((m,i)=><div className="hub-bar-column" key={m}><span>{money(values[i])}</span><div className="hub-bar-track"><i style={{height:Math.max(1,values[i]/max*100)+'%'}} title={m+': '+money(values[i])}/></div><small>{new Date(m+'-15').toLocaleString('en-GB',{month:'short'})}</small></div>)}</div>}
function Conversion(){const {s}=useHub(),m=metrics(s);return <div className="hub-conversion"><div className="hub-ring" style={{background:`conic-gradient(#d99462 ${m.conversion}%,#292b2e 0)`}}><strong>{m.conversion}<small>% converted</small></strong></div><div><b>{m.clients} clients</b><p>{m.leads} active enquiries</p><small>Clients and won leads as a share of all contacts.</small></div></div>}
function Clients(){const {s,profile}=useHub();const [query,setQuery]=useState(''),[status,setStatus]=useState(''),[treatment,setTreatment]=useState(''),[date,setDate]=useState('');const list=s.people.filter(p=>p.kind==='client'&&p.name.toLowerCase().includes(query.toLowerCase())&&(!status||p.status===status)&&(!treatment||p.treatment===treatment)&&(!date||s.appointments.some(a=>a.person===p.id&&a.date===date)));return <Card title={'Your clients · '+list.length}><div className="hub-filters"><input aria-label="Search clients" placeholder="⌕ Search clients…" value={query} onChange={e=>setQuery(e.target.value)}/><select aria-label="Treatment filter" value={treatment} onChange={e=>setTreatment(e.target.value)}><option value="">All treatments</option>{treatments.map(t=><option key={t}>{t}</option>)}</select><select aria-label="Status filter" value={status} onChange={e=>setStatus(e.target.value)}><option value="">All statuses</option>{['Completed','In treatment','Aftercare','Follow-up due'].map(t=><option key={t}>{t}</option>)}</select><label>Appointment date<input type="date" value={date} onChange={e=>setDate(e.target.value)}/></label></div><div className="hub-table-scroll"><table><thead><tr>{['Client','Treatment','Status','Last appointment','Next action','Total spend',''].map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{list.map(p=><tr key={p.id}><td><PersonLine id={p.id} sub={p.email}/></td><td>{p.treatment}</td><td><Badge>{p.status}</Badge></td><td>{s.appointments.filter(a=>a.person===p.id&&a.status==='Completed').sort((a,b)=>b.date.localeCompare(a.date))[0]?.date||'—'}</td><td>{s.tasks.find(t=>t.person===p.id&&!t.done)?.title||'No action due'}</td><td><strong>{money(s.payments.filter(x=>x.person===p.id).reduce((n,x)=>n+x.amount,0))}</strong></td><td><button className="hub-text-btn" onClick={()=>profile(p.id)}>View ↗</button></td></tr>)}</tbody></table></div>{!list.length&&<p className="hub-empty">No clients match these filters.</p>}</Card>}
function Pipeline(){const {s,change,notify,profile,open}=useHub();const origin=useRef<{id:string;x:number;y:number}|null>(null);const [drag,setDrag]=useState<{id:string;x:number;y:number}|null>(null);function move(id:string,status:string){const p=s.people.find(p=>p.id===id);if(!p||p.kind!=='lead'||p.status===status)return;change(d=>{d.people.find(p=>p.id===id)!.status=status;record(d,id,'Pipeline moved to '+status)});notify(status==='Won'?'A new chapter! Lead marked as won.':'Lead moved to '+status);if(status==='Won')open({type:'convert',person:id})}return <><div className="hub-pipeline-top"><span><strong>{metrics(s).leads}</strong> active enquiries</span><span><strong>{money(metrics(s).pipeline)}</strong> estimated pipeline</span><span>Drag a card, or use its stage selector.</span></div><div className="hub-kanban">{stages.map(stage=><section key={stage} data-stage={stage} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();move(e.dataTransfer.getData('text/plain'),stage)}}><h2><i/>{stage}<b>{s.people.filter(p=>p.kind==='lead'&&p.status===stage).length}</b></h2>{s.people.filter(p=>p.kind==='lead'&&p.status===stage).map(p=><article key={p.id} className="hub-lead" style={drag?.id===p.id?{transform:'translate('+drag.x+'px,'+drag.y+'px)',position:'relative',zIndex:5,pointerEvents:'none',boxShadow:'0 15px 35px #26321c30'}:undefined} onPointerDown={e=>{if((e.target as Element).closest('button,select,input'))return;e.preventDefault();origin.current={id:p.id,x:e.clientX,y:e.clientY};e.currentTarget.setPointerCapture(e.pointerId)}} onPointerMove={e=>{if(origin.current?.id===p.id)setDrag({id:p.id,x:e.clientX-origin.current.x,y:e.clientY-origin.current.y})}} onPointerUp={e=>{const start=origin.current;if(!start)return;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-stage]')?.getAttribute('data-stage');origin.current=null;setDrag(null);e.currentTarget.releasePointerCapture(e.pointerId);if(target&&Math.hypot(e.clientX-start.x,e.clientY-start.y)>8)move(p.id,target)}} onPointerCancel={()=>{origin.current=null;setDrag(null)}}><button className="hub-person" onClick={()=>profile(p.id)}><Avatar p={p}/><strong>{p.name}</strong></button><p>{p.treatment}</p><strong className="hub-deal">{money(p.value)}</strong><small>{p.source} · {nice(p.created)}</small><p className="hub-lead-note">{s.activity.find(a=>a.person===p.id)?.text||'Awaiting first conversation'}</p><small>Next: {s.tasks.find(t=>t.person===p.id&&!t.done)?.title||'Review next steps'}</small><select aria-label={'Stage for '+p.name} value={p.status} onChange={e=>move(p.id,e.target.value)}>{stages.map(x=><option key={x}>{x}</option>)}</select>{p.status==='Won'&&<button className="hub-text-btn" onClick={()=>open({type:'convert',person:p.id})}>Convert to client →</button>}</article>)}<div className="hub-drop-hint">Drop a lead here</div></section>)}</div></>}
function TaskRow({task}:{task:Task}){const {s,change,open}=useHub();return <div className="hub-task-row"><input type="checkbox" aria-label={'Complete '+task.title} checked={task.done} onChange={()=>change(d=>{d.tasks.find(t=>t.id===task.id)!.done=!task.done;record(d,task.person,task.done?'Task reopened: '+task.title:'Task completed: '+task.title)})}/><button onClick={()=>open({type:'task',id:task.id,person:task.person})}><strong style={{textDecoration:task.done?'line-through':'none'}}>{task.title}</strong><small>{s.people.find(p=>p.id===task.person)?.name} · {nice(task.date)}</small></button><Badge>{task.priority}</Badge></div>}
function Tasks(){const {s}=useHub();return <div className="hub-grid two">{['Overdue','Today','Upcoming','Completed'].map(group=><Card title={group} key={group}>{s.tasks.filter(t=>group==='Completed'?t.done:!t.done&&(group==='Overdue'?t.date<day():group==='Today'?t.date===day():t.date>day())).map(t=><TaskRow task={t} key={t.id}/>)}<p className="hub-chart-note">{group==='Completed'?'Completed actions stay here for your records.':'Select a task to edit its date, priority or details.'}</p></Card>)}</div>}
function Calendar(){const {s,open,change,notify}=useHub();const [view,setView]=useState('Month'),[date,setDate]=useState(day());const md=monthDays(date.slice(0,7));const monday=addDays(date,-((new Date(date+'T12:00:00Z').getUTCDay()+6)%7));const dates=view==='Month'?[...Array.from({length:md.offset},()=>null),...md.days]:view==='Week'?Array.from({length:7},(_,i)=>addDays(monday,i)):[date];function simulate(){const slot=nextSlot(s.appointments);if(!slot){notify('No example times remain in the next 60 days.');return}change(d=>{const id=uid();d.people.push({id,name:'Alex Taylor '+(d.people.length-24),kind:'lead',treatment:'Hairline restoration',status:'Consultation Booked',source:'Website',created:day(),email:'alex.demo@example.com',phone:'07700 900333',value:1900,notes:['Created using the simulated website booking.']});d.appointments.push({id:uid(),person:id,...slot,type:'Consultation',format:'Video',status:'Scheduled'});record(d,id,'Website consultation booking received.')});notify('Website booking added to the calendar and pipeline.')}return <Card title="Appointment calendar"><div className="hub-calendar-toolbar"><div><Button onClick={()=>setDate(view==='Month'?shiftMonth(date.slice(0,7),-1)+'-01':addDays(date,view==='Week'?-7:-1))}>←</Button><strong>{new Date(date+'T12:00:00Z').toLocaleString('en-GB',{month:'long',year:'numeric'})}</strong><Button onClick={()=>setDate(view==='Month'?shiftMonth(date.slice(0,7),1)+'-01':addDays(date,view==='Week'?7:1))}>→</Button><Button onClick={()=>setDate(day())}>Today</Button></div><div>{['Month','Week','Day'].map(v=><button className={'hub-btn '+(view===v?'selected':'')} onClick={()=>setView(v)} key={v}>{v}</button>)}<Button onClick={simulate}>↗ Simulate website booking</Button></div></div><p className="hub-chart-note">UK time · Consultations use the public calendar’s Friday availability, 09:00–17:00.</p><div className={'hub-calendar '+(view==='Day'?'day':'')}>{view!=='Day'&&['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=><b key={d}>{d}</b>)}{dates.map((d,i)=><div key={d||i} className={'hub-calendar-day '+(d===day()?'today':'')}><strong>{d?new Date(d+'T12:00:00Z').getUTCDate():''}</strong>{d&&s.appointments.filter(a=>a.date===d).sort((a,b)=>a.time.localeCompare(b.time)).map(a=><button key={a.id} className={'hub-calendar-event '+a.type.toLowerCase()+(a.status==='Cancelled'?' cancelled':'')} onClick={()=>open({type:'appointment',id:a.id,person:a.person})}><b>{a.time} · {a.type}</b><span>{s.people.find(p=>p.id===a.person)?.name}</span><small>{a.status}</small></button>)}</div>)}</div><div className="hub-legend"><span>● Consultation</span><span>● Treatment</span><span>● Follow-up</span><span>○ Cancelled</span></div></Card>}
function Inbox(){const {s,change,notify,profile,open}=useHub();const [selected,setSelected]=useState('l4'),[query,setQuery]=useState(''),[text,setText]=useState(''),[archived,setArchived]=useState(false);const p=s.people.find(p=>p.id===selected)||s.people[0];const messages=s.messages.filter(m=>m.person===p.id);const people=s.people.filter(p=>s.messages.some(m=>m.person===p.id)&&s.archived.includes(p.id)===archived&&p.name.toLowerCase().includes(query.toLowerCase()));function pick(id:string){setSelected(id);setText('');change(d=>{d.messages.filter(m=>m.person===id).forEach(m=>m.read=true)})}return <div className="hub-inbox"><section className="hub-conversations"><div className="hub-inbox-title"><h2>Conversations</h2><Badge>{people.length}</Badge></div><input placeholder="Search conversations…" aria-label="Search conversations" value={query} onChange={e=>setQuery(e.target.value)}/><label className="hub-checkbox"><input type="checkbox" checked={archived} onChange={e=>setArchived(e.target.checked)}/> Show archived</label>{people.map(person=><button className={'hub-conversation '+(person.id===p.id?'active':'')} key={person.id} onClick={()=>pick(person.id)}><Avatar p={person}/><span><strong>{person.name}{s.messages.some(m=>m.person===person.id&&!m.read)&&<i/>}</strong><small>{s.messages.filter(m=>m.person===person.id).at(-1)?.text.slice(0,65)}</small></span></button>)}</section><section className="hub-message-panel"><div className="hub-message-header"><PersonLine id={p.id}/><Button onClick={()=>{change(d=>{d.archived=d.archived.includes(p.id)?d.archived.filter(x=>x!==p.id):[...d.archived,p.id]});notify('Conversation '+(archived?'restored':'archived'))}}>{s.archived.includes(p.id)?'Restore':'Archive'}</Button></div><div className="hub-messages">{messages.map(m=><div className={'hub-message '+(m.out?'out':'')} key={m.id}><small>{m.out?'Joe · simulated email':p.name} · {nice(m.date)}</small><p>{m.text}</p></div>)}</div><form className="hub-compose" onSubmit={e=>{e.preventDefault();if(!text.trim())return;change(d=>send(d,p.id,text.trim()));setText('');notify('Message added to the conversation. No email delivered.')}}><select aria-label="Insert saved template" defaultValue="" onChange={e=>{const t=s.templates.find(t=>t.id===e.target.value);if(t)setText(personalise(t.body,p,s));e.target.value=''}}><option value="">Insert a saved template…</option>{s.templates.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select><textarea required aria-label="Your reply" placeholder="Write a thoughtful reply…" value={text} onChange={e=>setText(e.target.value)}/><div><small>Messages stay in this workspace.</small><button className="hub-btn primary">Simulate send ↗</button></div></form></section><aside className="hub-customer-panel"><Avatar p={p}/><h2>{p.name}</h2><Badge>{p.status}</Badge><p>{p.treatment}</p><dl><dt>Email</dt><dd>{p.email}</dd><dt>Source</dt><dd>{p.source}</dd><dt>Customer since</dt><dd>{nice(p.created)}</dd></dl><Button onClick={()=>profile(p.id)}>View full profile ↗</Button><Button onClick={()=>open({type:'task',person:p.id})}>＋ Follow-up task</Button></aside></div>}
function Templates(){const {s,change,notify}=useHub();const [id,setId]=useState(s.templates[0].id),[customer,setCustomer]=useState('l4');const t=s.templates.find(t=>t.id===id)||s.templates[0],p=s.people.find(p=>p.id===customer)!;const [subject,setSubject]=useState(t.subject),[body,setBody]=useState(t.body);function pick(t:Template){setId(t.id);setSubject(t.subject);setBody(t.body)}return <div className="hub-template-layout"><Card title="Your templates">{s.templates.map(t=><button className={'hub-template-pick '+(t.id===id?'active':'')} key={t.id} onClick={()=>pick(t)}>✉ <span>{t.name}</span> →</button>)}</Card><Card title={t.name}><div className="hub-form"><label>Subject<input value={subject} onChange={e=>setSubject(e.target.value)}/></label><label>Message</label><RichEditor value={body} onChange={setBody}/><div className="hub-button-row"><Button primary onClick={()=>{change(d=>{const t=d.templates.find(t=>t.id===id)!;t.subject=subject;t.body=body});notify('Template saved')}}>Save template</Button><Button onClick={()=>{const copy={...t,id:uid(),name:t.name+' (copy)',subject,body};change(d=>{d.templates.push(copy)});pick(copy);notify('Template duplicated')}}>Duplicate</Button></div></div></Card><Card title="Email preview"><label className="hub-field">Preview for<select value={customer} onChange={e=>setCustomer(e.target.value)}>{s.people.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><div className="hub-email-preview"><div>HAIRLUSION<small>PERSONAL CARE. CONSIDERED DETAIL.</small></div><h3>{personalise(subject,p,s)}</h3><RichText text={personalise(body,p,s)}/><footer>Joe · Hairlusion<br/>Scalp micropigmentation</footer></div><Button primary onClick={()=>{change(d=>send(d,p.id,personalise(subject,p,s)+'\n\n'+personalise(body,p,s)));notify('Personalised email added to '+p.name+'’s conversation.')}}>Simulate send ↗</Button></Card></div>}
function RichText({text}:{text:string}){return <div className="hub-rich-text">{text.split('\n').map((line,i)=><p key={i}>{line.split(/(\*\*.*?\*\*)/g).map((part,j)=>part.startsWith('**')?<strong key={j}>{part.slice(2,-2)}</strong>:part)||'\u00a0'}</p>)}</div>}
function Automations(){const {s,change,notify}=useHub();const [running,setRunning]=useState('');const timer=useRef<ReturnType<typeof setTimeout>|null>(null);useEffect(()=>()=>{if(timer.current)clearTimeout(timer.current)},[]);function run(id:string){const w=s.workflows.find(w=>w.id===id)!;if(!w.enabled||running)return;const target=w.name.includes('follow-up')?s.quotes.find(q=>q.status==='Sent')?.person:w.name==='New enquiry'?s.people.find(p=>p.status==='New Enquiry')?.id:w.name==='No response'?s.people.find(p=>p.status==='New Enquiry'&&!s.messages.some(m=>m.person===p.id&&m.out))?.id:w.name==='Post-consultation'?s.appointments.find(a=>a.type==='Consultation'&&a.status==='Completed')?.person:w.name==='Aftercare'||w.name==='Review invitation'?'c0':s.appointments.find(a=>a.type==='Consultation'&&a.status==='Scheduled')?.person;if(!target){notify('No eligible record matches this workflow.');return}const p=s.people.find(p=>p.id===target)!;const t=s.templates.find(t=>t.id===w.template)!;setRunning(id);timer.current=setTimeout(()=>{change(d=>{if(['No response','Post-consultation'].includes(w.name)){d.tasks.push({id:uid(),person:p.id,title:w.name==='No response'?'Follow up unanswered enquiry':'Follow up consultation',date:day(),priority:'Normal',done:false});record(d,p.id,'Automation created a follow-up task.')}else send(d,p.id,personalise(t.subject,p,s)+'\n\n'+personalise(t.body,p,s));d.workflows.find(x=>x.id===id)!.history.unshift(new Date().toLocaleString('en-GB')+' · '+p.name+' · Simulated after '+w.delay+' hours · Completed')});setRunning('');notify('Workflow completed for '+p.name)},1100)}return <><div className="hub-soft"><strong>Good care, thoughtfully timed.</strong><p>Run previews the action after its configured delay, without waiting. Workflows do not run in the background or send real emails.</p></div><div className="hub-grid two">{s.workflows.map(w=><Card key={w.id} title={w.name}><div className="hub-workflow-head"><Badge>{w.enabled?'Active':'Paused'}</Badge><label className="hub-switch"><input type="checkbox" checked={w.enabled} onChange={e=>change(d=>{d.workflows.find(x=>x.id===w.id)!.enabled=e.target.checked})}/> Enabled</label></div><div className="hub-flow"><div><small>TRIGGER</small><strong>{w.trigger}</strong></div><span>→</span><div><small>DELAY</small><label><input type="number" min="0" max="8760" aria-label={'Delay hours for '+w.name} value={w.delay} onChange={e=>change(d=>{d.workflows.find(x=>x.id===w.id)!.delay=Math.max(0,Number(e.target.value))})}/> hours</label></div><span>→</span><div><small>CONDITION</small><strong>Eligible record</strong></div><span>→</span><div><small>ACTION</small><strong>{['No response','Post-consultation'].includes(w.name)?'Create task':'Prepare email'}</strong></div></div><label className="hub-field">Email template<select value={w.template} onChange={e=>change(d=>{d.workflows.find(x=>x.id===w.id)!.template=e.target.value})}>{s.templates.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select></label><button className="hub-btn" disabled={!w.enabled||!!running} onClick={()=>run(w.id)}>{running===w.id?'Preparing personalised response…':'▷ Run automation'}</button><details className="hub-history"><summary>Activity history · {w.history.length}</summary>{w.history.length?w.history.map((h,i)=><p key={i}>{h}</p>):<p>No simulations run yet.</p>}</details></Card>)}</div></>}
function Illustration({variant=0,after=false}:{variant?:number;after?:boolean}){const skin=['#b98566','#d8b18b','#9b6e52','#e0bfa7'][variant%4];return <svg viewBox="0 0 400 300" role="img" aria-label={'Illustrative scalp diagram · '+(after?'after':'before')+' · not a patient photograph'}><defs><clipPath id={'head'+variant+after}><ellipse cx="200" cy="155" rx={85+variant%3*7} ry="119"/></clipPath><radialGradient id={'skin'+variant+after}><stop stopColor={skin}/><stop offset="1" stopColor="#766151"/></radialGradient><pattern id={'dots'+variant+after} width={after?5:12} height={after?5:12} patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r={after?1.1:.65} fill="#493c34" opacity=".7"/></pattern></defs><rect width="400" height="300" fill={['#e7e3dd','#d9e0db','#e3dfdc','#dddfe3'][variant%4]}/><ellipse cx="200" cy="292" rx="140" ry="65" fill="#484b47"/><ellipse cx="200" cy="155" rx={85+variant%3*7} ry="119" fill={'url(#skin'+variant+after+')'}/><path d="M110 170 Q100 35 200 35 Q300 35 290 170 Q260 99 200 113 Q140 99 110 170" fill={'url(#dots'+variant+after+')'} clipPath={'url(#head'+variant+after+')'}/><path d="M173 228 Q200 242 227 228" fill="none" stroke="#6e5043" strokeWidth="3"/><text x="18" y="25" fontSize="10" letterSpacing="2" fill="#5a625e">ILLUSTRATIVE STUDY {String(variant+1).padStart(2,'0')}</text><text x="18" y="280" fontSize="11" fill="#fff">{after?'AFTER · CONCEPT ONLY':'BEFORE · CONCEPT ONLY'}</text></svg>}
function Comparison({variant=0}:{variant?:number}){const [value,setValue]=useState(50);return <div><div className="hub-compare"><Illustration variant={variant} after/><div style={{clipPath:`inset(0 ${100-value}% 0 0)`}}><Illustration variant={variant}/></div><span style={{left:value+'%'}}>↔</span><input aria-label="Compare illustrative before and after" type="range" min="0" max="100" value={value} onChange={e=>setValue(Number(e.target.value))}/></div><small className="hub-chart-note">Illustrative diagram only. Not a patient photograph or treatment outcome.</small></div>}
function Photos(){const {s,open}=useHub();const [filter,setFilter]=useState('All');const cats=['Before treatment','Treatment progress','After treatment','Hairline work','Crown density','Scar camouflage'];return <><div className="hub-photo-heading"><div className="hub-tabs">{['All',...cats].map(c=><button key={c} className={filter===c?'active':''} onClick={()=>setFilter(c)}>{c}</button>)}</div><p>Labelled concept studies · No genuine patient photographs</p></div><div className="hub-photo-grid">{s.people.filter(p=>p.kind==='client').slice(0,18).map((p,i)=>({p,i,cat:cats[i%6]})).filter(x=>filter==='All'||x.cat===filter).map(({p,i,cat})=><button className="hub-photo-card" key={p.id} onClick={()=>open({type:'photo',person:p.id})}><Illustration variant={i} after={i%3===2}/><div><Badge>{cat}</Badge><strong>{p.name}</strong><small>{p.treatment} · Illustration</small><span>Explore comparison ↗</span></div></button>)}</div></>}
function Reports(){const {s}=useHub();const [from,setFrom]=useState(day(-180)),[to,setTo]=useState(day());const people=s.people.filter(p=>p.created>=from&&p.created<=to),quotes=s.quotes.filter(q=>q.date>=from&&q.date<=to),payments=s.payments.filter(p=>p.date>=from&&p.date<=to);const rate=(n:number,total:number)=>total?Math.round(n/total*100)+'%':'—';const responded=s.messages.filter(m=>m.out&&m.date.slice(0,10)>=from&&m.date.slice(0,10)<=to).map(m=>{const first=s.messages.filter(x=>x.person===m.person&&!x.out&&x.date<m.date).at(-1);return first?(new Date(m.date).getTime()-new Date(first.date).getTime())/3600000:null}).filter((x):x is number=>x!==null);return <><div className="hub-filters"><label>From<input type="date" value={from} max={to} onChange={e=>setFrom(e.target.value)}/></label><label>To<input type="date" value={to} min={from} onChange={e=>setTo(e.target.value)}/></label><span>Reports use recorded events within your chosen dates.</span></div><div className="hub-kpis">{[['Enquiries',people.length],['Consultation booking rate',rate(people.filter(p=>s.appointments.some(a=>a.person===p.id&&a.type==='Consultation'&&a.status!=='Cancelled')).length,people.length)],['Quote acceptance',rate(quotes.filter(q=>q.status==='Accepted').length,quotes.length)],['Client conversion',rate(people.filter(p=>p.kind==='client'||p.status==='Won').length,people.length)],['Revenue',money(payments.reduce((n,p)=>n+p.amount,0))],['Outstanding enquiries',people.filter(p=>p.kind==='lead'&&!['Won','Lost'].includes(p.status)).length],['Average response time',responded.length?(responded.reduce((a,b)=>a+b,0)/responded.length).toFixed(1)+'h':'No replies yet']].map(([label,value])=><div className="hub-kpi" key={label}><span>{label}</span><strong>{value}</strong></div>)}</div><div className="hub-grid two"><Card title="Revenue over time"><RevenueChart from={from} to={to}/></Card><Card title="Revenue by treatment">{treatments.map(t=>{const value=payments.filter(p=>s.people.find(x=>x.id===p.person)?.treatment===t).reduce((n,p)=>n+p.amount,0);return <div className="hub-report-row" key={t}><span>{t}</span><b>{money(value)}</b><i style={{width:value/Math.max(1,...treatments.map(t=>payments.filter(p=>s.people.find(x=>x.id===p.person)?.treatment===t).reduce((n,p)=>n+p.amount,0)))*100+'%'}}/></div>})}</Card><Card title="Enquiries by source">{['Website','Instagram','Referral','Google'].map(source=><div className="hub-list-row" key={source}><span>{source}</span><strong>{people.filter(p=>p.source===source).length}</strong></div>)}</Card><Card title="Monthly enquiries">{Array.from({length:6},(_,i)=>shiftMonth(day().slice(0,7),i-5)).map(month=><div className="hub-list-row" key={month}><span>{new Date(month+'-15').toLocaleString('en-GB',{month:'long'})}</span><strong>{people.filter(p=>p.created.startsWith(month)).length}</strong></div>)}</Card></div></>}
function Settings(){const {s,change,open,notify}=useHub();return <div className="hub-grid two"><Card title="Workspace preferences"><form className="hub-form" onSubmit={e=>{e.preventDefault();notify('Workspace preferences saved')}}><label>Business name<input value={s.settings.business} onChange={e=>change(d=>{d.settings.business=e.target.value})}/></label><label>Administrator email<input type="email" value={s.settings.email} onChange={e=>change(d=>{d.settings.email=e.target.value})}/></label><label className="hub-checkbox"><input type="checkbox" checked={s.settings.notifications} onChange={e=>change(d=>{d.settings.notifications=e.target.checked})}/> Show reminder notifications</label><button className="hub-btn primary">Save preferences</button></form></Card><Card title="Sample data & privacy"><p>This workspace contains fictional contacts, financial figures, conversations and treatment histories. Illustrations are labelled concepts, not genuine patient photographs.</p><p>Changes are saved in this browser. No login, database, message delivery or external calendar is connected. Use fictional information only.</p><p>Resetting restores the original 20 clients and five leads, and clears changes made to the sample workspace.</p><Button onClick={()=>open({type:'reset'})}>Reset sample data</Button></Card></div>}
function ModalView({modal,close}:{modal:Modal;close:()=>void}){const ref=useRef<HTMLDialogElement>(null);useEffect(()=>{const el=ref.current;el?.showModal();const old=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{el?.close();document.body.style.overflow=old}},[]);return <dialog ref={ref} className={'hub-modal '+(modal.type==='profile'?'wide':'')} onCancel={close} onClick={e=>{if(e.target===ref.current){const r=ref.current!.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}}} aria-label={modal.type==='profile'?'Customer profile':modal.type}><div className="hub-modal-bar"><span>HAIRLUSION CLIENTHUB</span><button aria-label="Close dialog" onClick={close}>×</button></div><div className="hub-modal-body">{modal.type==='profile'?<Profile person={modal.person!}/>:modal.type==='photo'?<PhotoDetail person={modal.person!}/>:<EditForm key={modal.type+modal.id+modal.person} modal={modal} close={close}/>}</div></dialog>}
function PhotoDetail({person}:{person:string}){const {s,profile}=useHub(),p=s.people.find(p=>p.id===person)!;return <><h2>{p.name}</h2><p>{p.treatment} · Illustrative comparison</p><Comparison variant={s.people.indexOf(p)}/><Button onClick={()=>profile(person)}>Open client profile ↗</Button></>}
function Profile({person}:{person:string}){const {s,open,change,notify}=useHub(),p=s.people.find(p=>p.id===person)!;const [tab,setTab]=useState('Overview');const appointments=s.appointments.filter(a=>a.person===person),quotes=s.quotes.filter(q=>q.person===person);return <><div className="hub-profile-head"><Avatar p={p}/><div><h2>{p.name}</h2><p>{p.treatment}</p></div><Badge>{p.status}</Badge></div><div className="hub-profile-actions">{[['note','Add note'],['email','Send email'],['appointment','Schedule appointment'],['quote','Create quotation'],['task','Add reminder']].map(([type,label])=><Button key={type} onClick={()=>open({type,person})}>{label}</Button>)}<select aria-label="Update customer status" value={p.status} onChange={e=>{const status=e.target.value;change(d=>{d.people.find(x=>x.id===person)!.status=status;record(d,person,'Status updated to '+status)});notify('Customer status updated');if(status==='Won')open({type:'convert',person})}}>{(p.kind==='lead'?stages:['Completed','In treatment','Aftercare','Follow-up due']).map(x=><option key={x}>{x}</option>)}</select></div><div className="hub-journey">{['Enquiry','Consultation','Quotation','Treatment','Aftercare','Follow-up'].map((x,i)=><div className={(i===0||i===1&&appointments.some(a=>a.type==='Consultation')||i===2&&quotes.length||i===3&&appointments.some(a=>a.type==='Treatment')||i===4&&['Aftercare','Completed','Follow-up due'].includes(p.status)||i===5&&p.status==='Completed')?'done':''} key={x}><span>{i+1}</span>{x}</div>)}</div><div className="hub-tabs">{['Overview','Timeline','Photographs','Quotations','Conversations'].map(t=><button key={t} className={tab===t?'active':''} onClick={()=>setTab(t)}>{t}</button>)}</div>{tab==='Overview'?<div className="hub-grid two"><Card title="Personal details"><dl className="hub-details"><dt>Email</dt><dd>{p.email}</dd><dt>Telephone</dt><dd>{p.phone}</dd><dt>Enquiry source</dt><dd>{p.source}</dd><dt>First contacted</dt><dd>{nice(p.created)}</dd><dt>Total paid</dt><dd>{money(s.payments.filter(x=>x.person===person).reduce((n,x)=>n+x.amount,0))}</dd></dl></Card><Card title="Internal notes">{p.notes.map((n,i)=><p className="hub-note" key={i}>{n}</p>)}</Card><Card title="Treatment plan & appointments"><p>{p.treatment}. Consultation-led plan with staged sessions, progress review and personalised aftercare.</p>{appointments.map(a=><button key={a.id} className="hub-appointment-line" onClick={()=>open({type:'appointment',id:a.id,person})}><strong>{a.type}</strong><span>{nice(a.date)} · {a.time}</span><Badge>{a.status}</Badge></button>)}</Card><Card title="Next actions">{s.tasks.filter(t=>t.person===person&&!t.done).map(t=><TaskRow key={t.id} task={t}/>)}<Button onClick={()=>open({type:'task',person})}>＋ Add a thoughtful follow-up</Button></Card></div>:tab==='Timeline'?<div>{[...s.activity].filter(a=>a.person===person).sort((a,b)=>b.date.localeCompare(a.date)).map(a=><div className="hub-activity" key={a.id}><i/><div><strong>{a.text}</strong><small>{nice(a.date)}</small></div></div>)}</div>:tab==='Photographs'?<><Comparison variant={s.people.indexOf(p)}/><div className="hub-grid three">{['Before','Progress','After'].map((x,i)=><figure key={x}><Illustration variant={s.people.indexOf(p)+i} after={i===2}/><figcaption>{x} · Illustrative placeholder</figcaption></figure>)}</div></>:tab==='Quotations'?<>{quotes.map(q=><div className="hub-quote-preview" key={q.id}><div><strong>HAIRLUSION</strong><span>QUOTATION · {q.id.slice(0,8).toUpperCase()}</span></div><h3>Prepared for {p.name}</h3><p>{nice(q.date)}</p><div className="hub-list-row"><span>{p.treatment}</span><strong>{money(q.amount)}</strong></div><p>{q.notes}</p><Badge>{q.status}</Badge><p className="hub-chart-note">Illustrative pricing only. This is not a payable quotation.</p><Button onClick={()=>open({type:'quote',id:q.id,person})}>Edit quotation</Button></div>)}{!quotes.length&&<p>No quotation created yet.</p>}</>:<>{s.messages.filter(m=>m.person===person).map(m=><div className={'hub-message '+(m.out?'out':'')} key={m.id}><small>{m.out?'Joe · simulated':p.name} · {nice(m.date)}</small><p>{m.text}</p></div>)}</>}</>}
function EditForm({modal,close}:{modal:Modal;close:()=>void}){const {s,change,notify,profile}=useHub();const {type,id}=modal;const appointment=s.appointments.find(a=>a.id===id),quote=s.quotes.find(q=>q.id===id),task=s.tasks.find(t=>t.id===id);const slot=nextSlot(s.appointments);const [person,setPerson]=useState(modal.person||s.people[0].id),[date,setDate]=useState(appointment?.date||task?.date||slot?.date||day()),[time,setTime]=useState(appointment?.time||slot?.time||'09:00'),[appointmentType,setAppointmentType]=useState(appointment?.type||'Consultation'),[status,setStatus]=useState(appointment?.status||quote?.status||'Draft'),[amount,setAmount]=useState(quote?.amount||s.people.find(p=>p.id===person)?.value||1800),[message,setMessage]=useState(''),[error,setError]=useState('');const p=s.people.find(p=>p.id===person)!;const available=slotsFor(date).filter(x=>x.available&&!s.appointments.some(a=>a.id!==id&&a.status==='Scheduled'&&a.date===date&&a.time===x.time));
 function save(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setError('');const form=new FormData(e.currentTarget),get=(key:string)=>String(form.get(key)||'').trim();
 if(type==='appointment'&&status!=='Cancelled'&&status!=='Completed'&&(!available.some(x=>x.time===time))){setError('Choose an available Friday time. Existing scheduled appointments cannot overlap.');return}
 change(d=>{if(type==='lead'||type==='client'){const name=get('name');const newPerson:Person={id:uid(),name,kind:type,treatment:get('treatment'),status:type==='lead'?'New Enquiry':'In treatment',source:get('source'),created:day(),email:get('email'),phone:get('phone'),value:Number(get('value')),notes:get('notes')?[get('notes')]:[]};d.people.push(newPerson);record(d,newPerson.id,'New '+type+' added to ClientHub.')}
 if(type==='note'){d.people.find(x=>x.id===person)!.notes.push(get('notes'));record(d,person,'Internal note added.')}
 if(type==='email')send(d,person,get('subject')+'\n\n'+message);
 if(type==='appointment'){const item:Appointment={id:id||uid(),person,date,time,type:appointmentType,format:get('format'),status:id?status:'Scheduled'};if(id)d.appointments=d.appointments.map(a=>a.id===id?item:a);else d.appointments.push(item);const p=d.people.find(p=>p.id===person)!;if(p.kind==='lead'&&item.type==='Consultation'&&item.status==='Scheduled'&&['New Enquiry','Contacted'].includes(p.status))p.status='Consultation Booked';record(d,person,(id?'Appointment updated: ':'Appointment scheduled: ')+appointmentType+' · '+nice(date)+' '+time)}
 if(type==='task'){const item:Task={id:id||uid(),person,title:get('title'),date,priority:get('priority'),done:task?.done||false};if(id)d.tasks=d.tasks.map(t=>t.id===id?item:t);else d.tasks.push(item);record(d,person,id?'Reminder updated.':'Reminder added: '+item.title)}
 if(type==='quote'){const item:Quote={id:id||uid(),person,amount:Number(amount),date:quote?.date||day(),status,notes:get('notes')};if(id)d.quotes=d.quotes.map(q=>q.id===id?item:q);else d.quotes.push(item);const p=d.people.find(p=>p.id===person)!;p.value=Number(amount);if(p.kind==='lead'&&status==='Sent'&&!['Won','Lost'].includes(p.status))p.status='Quote Sent';record(d,person,'Quotation '+status.toLowerCase()+' · '+money(Number(amount)))}
 if(type==='convert'){const p=d.people.find(p=>p.id===person)!;p.kind='client';p.status='In treatment';d.quotes.filter(q=>q.person===person&&q.status==='Sent').forEach(q=>q.status='Accepted');d.tasks.filter(t=>t.person===person&&t.title.toLowerCase().includes('quotation')).forEach(t=>t.done=true);d.tasks.push({id:uid(),person,title:'Arrange first treatment session',date:day(1),priority:'Normal',done:false});record(d,person,'Won lead converted into a client. Treatment planning begins.')}
 if(type==='reset'){Object.assign(d,seed())}
 });notify(type==='reset'?'Original sample workspace restored.':type==='convert'?'Welcome to your client list, '+p.name+'.':'Saved to your workspace.');if(type==='convert')profile(person);else close()}
 const titles:Record<string,string>={lead:'A new conversation.',client:'Welcome a new client.',appointment:id?'Appointment details.':'Make time for a conversation.',task:id?'A thoughtful reminder.':'What needs your attention?',quote:id?'Refine this quotation.':'A considered quotation.',note:'A little more context.',email:'A personal message.',convert:'A new chapter begins.',reset:'Start fresh with sample data.'};
 return <form className="hub-form" onSubmit={save}><h2>{titles[type]||type}</h2>{['convert','reset'].includes(type)?<><p>{type==='convert'?p.name+' is ready for the next step. Convert this won lead into a client and accept any outstanding quotation. This does not record a payment.':'This clears your local edits, messages and new records, and restores the original fictional workspace.'}</p><div className="hub-button-row"><button className="hub-btn primary">{type==='convert'?'Convert to client':'Reset sample data'}</button><Button onClick={close}>Keep as is</Button></div></>:<>{!['lead','client'].includes(type)&&<label>Customer<select value={person} onChange={e=>setPerson(e.target.value)}>{s.people.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label>}{['lead','client'].includes(type)&&<><label>Full name<input name="name" required maxLength={100} placeholder="Fictional customer name"/></label><div className="hub-form-grid"><label>Email<input name="email" type="email" required placeholder="name@example.com"/></label><label>Telephone<input name="phone" placeholder="07700 900123"/></label></div><label>Treatment interest<select name="treatment">{treatments.map(t=><option key={t}>{t}</option>)}</select></label><div className="hub-form-grid"><label>Source<select name="source">{['Website','Instagram','Referral','Google'].map(t=><option key={t}>{t}</option>)}</select></label><label>Estimated value (£)<input name="value" type="number" min="0" max="100000" defaultValue="1800" required/></label></div><label>Administrative notes<textarea name="notes"/></label></>}{type==='note'&&<label>Internal note<textarea name="notes" required maxLength={3000}/></label>}{type==='email'&&<><label>Subject<input name="subject" required defaultValue="A personal follow-up from Joe"/></label><select aria-label="Use email template" defaultValue="" onChange={e=>{const t=s.templates.find(t=>t.id===e.target.value);if(t)setMessage(personalise(t.body,p,s))}}><option value="">Use a saved template…</option>{s.templates.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select><label>Your message<textarea required value={message} onChange={e=>setMessage(e.target.value)}/></label><small>This adds a simulated email to the inbox. Nothing is delivered.</small></>}{type==='appointment'&&<><div className="hub-form-grid"><label>Appointment type<select value={appointmentType} onChange={e=>setAppointmentType(e.target.value)}>{['Consultation','Treatment','Follow-up'].map(t=><option key={t}>{t}</option>)}</select></label><label>Format<select name="format" defaultValue={appointment?.format||'Video'}>{['Telephone','Video','In person'].map(t=><option key={t}>{t}</option>)}</select></label></div><label>Date<input type="date" required value={date} onChange={e=>{setDate(e.target.value);setTime('')}}/></label><label>Start time · UK time<select required value={time} onChange={e=>setTime(e.target.value)}><option value="">Choose an available time</option>{appointment&&appointment.date===date&&!available.some(a=>a.time===appointment.time)&&<option value={appointment.time}>{appointment.time} · existing appointment</option>}{available.map(a=><option key={a.time}>{a.time}</option>)}</select></label><small>Uses the same illustrative Friday slots as the public booking calendar. No overlapping scheduled appointments.</small>{id&&<label>Status<select value={status} onChange={e=>setStatus(e.target.value)}>{['Scheduled','Completed','Cancelled'].map(t=><option key={t}>{t}</option>)}</select></label>}</>}{type==='task'&&<><label>Task<input name="title" required defaultValue={task?.title} maxLength={180}/></label><div className="hub-form-grid"><label>Due date<input type="date" value={date} onChange={e=>setDate(e.target.value)} required/></label><label>Priority<select name="priority" defaultValue={task?.priority||'Normal'}>{['Low','Normal','High'].map(t=><option key={t}>{t}</option>)}</select></label></div></>}{type==='quote'&&<><div className="hub-form-grid"><label>Illustrative amount (£)<input required type="number" min="1" max="100000" value={amount} onChange={e=>setAmount(Number(e.target.value))}/></label><label>Status<select value={status} onChange={e=>setStatus(e.target.value)}>{['Draft','Sent','Accepted','Declined','Expired'].map(t=><option key={t}>{t}</option>)}</select></label></div><label>Quotation notes<textarea name="notes" defaultValue={quote?.notes||'Illustrative treatment package. Final plan subject to consultation.'}/></label><div className="hub-quote-preview"><strong>HAIRLUSION</strong><h3>Prepared for {p.name}</h3><div className="hub-list-row"><span>{p.treatment}</span><strong>{money(amount)}</strong></div><Badge>{status}</Badge><small>Sample quotation · Not payable</small></div></>}{error&&<p role="alert" className="hub-error">{error}</p>}<div className="hub-button-row"><button className="hub-btn primary">{type==='email'?'Simulate send ↗':'Save '+(type==='quote'?'quotation':type)}</button><Button onClick={close}>Cancel</Button></div></>}</form>
}




